@import '../components/iso/iso.css';
@import '../components/motion/scene-equation.css';

/*
 * Robot Wiki runtime tokens (Tailwind v4 CSS-first), the Pantheon
 * research-page standard (owner decision of 2026-10-10, PANTHEON-SPEC.md).
 * Paper and ink, hairline 1px rules, grayscale chart colours and one muted
 * blue accent. The page is a single paper sheet in the very light warm grey
 * of the owner's prototype (#fafaf8): there is no second "reading surface"
 * colour, and the only inset is --paper-deep.
 *
 * The spec's own names live on :root below (--paper, --ink, --line, ...);
 * figures and primitives consume those directly. The --color-* names here
 * are the Tailwind utility layer over the same values. Renderer mirrors
 * live in lib/brand-v2-tokens.ts.
 */
:root {
  --paper: #fafaf8;
  --paper-deep: #f0f3f6;
  --ink: #1c1c1a;
  --muted: #6c6b66;
  --line: rgba(28, 28, 26, 0.14);
  --line-strong: rgba(28, 28, 26, 0.22);
  --chart-background: #dededb;
  --chart-medium: #a3a39e;
  --chart-dark: #3f3f3b;
  --accent: #3b6ea8;
  --ok: #1a6f45;
  --fail: #a52a1e;

  --page-gutter: clamp(24px, 8vw, 160px);
  --header-gutter: clamp(16px, 4vw, 80px);
  --code-radius: 7px;
}

@theme {
  /* Palette. Keep uppercase hex for executable parity with the mirror. */
  --color-ink: #1C1C1A;
  --color-graphite: #3F3F3B;
  --color-concrete: #DEDEDB;
  --color-paper: #FAFAF8;
  --color-white: #FFFFFF;
  --color-highlight: #A3A39E;
  --color-signal: #3B6EA8;

  /* Outcome marks (a small check or cross), never fills or series. */
  --color-ok: #1A6F45;
  --color-warn: #8A5A00;
  --color-error: #A52A1E;
  --color-destructive: #6B1839;
  --color-on-ok: #FFFFFF;
  --color-on-warn: #FFFFFF;
  --color-on-error: #FFFFFF;
  --color-on-destructive: #FFFFFF;

  /* Actions and focus are ink; the accent is the one highlighted series.
     Highlight and selection are neutral greys that ink text reads on. */
  --color-action: var(--color-ink);
  --color-on-action: var(--color-white);
  --color-selection: var(--color-concrete);
  --color-focus: var(--color-ink);
  --color-link: var(--color-ink);
  --color-registration: var(--color-signal);
  --color-active-path: var(--color-signal);

  /* One paper sheet; the inset is --paper-deep. */
  --color-bg: var(--color-paper);
  --color-surface: var(--color-paper);
  --color-surface-2: #F0F3F6;
  --color-border: rgba(28, 28, 26, 0.14);
  --color-border-strong: rgba(28, 28, 26, 0.22);
  --color-text: var(--color-ink);
  --color-text-dim: #6C6B66;

  /*
   * Compatibility aliases keep existing consumers stable while later
   * component features migrate them to the narrower semantic roles.
   */
  --color-accent: var(--color-signal);
  --color-err: var(--color-error);

  /*
   * The plate a third-party company mark sits on (components/market-map/
   * company-logo.tsx). Not a surface step: a deliberate mid neutral, because
   * the mark set spans both extremes and no single light ground holds it.
   * 35 of the 111 shipped marks are near-white (mean relative luminance
   * above 0.60) and 41 are near-black, so a paper-coloured tile loses the
   * first group and a near-black tile loses the second. This value sits at
   * relative luminance 0.20, the point where pure white and the text colour
   * are equidistant, giving both about 4.1:1. Every mark gets the same
   * plate; nothing is special-cased per company.
   */
  --color-logo-plate: #7d7a73;

  /* Typography: DM Sans display, Geist text and interface, Geist Mono for
     numerals, code and readouts. Variables are set by next/font in
     layout.tsx. The reading role is Geist too: one text face. */
  --font-display: var(--font-dm-sans), var(--font-geist), Arial, Helvetica,
    sans-serif;
  --font-sans: var(--font-geist), Arial, Helvetica, sans-serif;
  --font-serif: var(--font-geist), Arial, Helvetica, sans-serif;
  --font-mono: var(--font-geist-mono), ui-monospace, SFMono-Regular, Consolas,
    monospace;

  /* Square corners everywhere; the code block's 7px is --code-radius. */
  --radius-none: 0px;
  --radius-xs: 0px;
  --radius-sm: 0px;
  --radius-md: 0px;
  --radius-lg: 0px;
  --radius-xl: 0px;
  --shadow-raised: 0 0 #0000;
  --shadow-floating: 0 0 #0000;
}

/*
 * Display roles. The H1 is DM Sans 400; section and chrome roles are DM Sans
 * 600. Keep these in lockstep with data/type-roles.json.
 */
.font-display-home,
.font-display-page,
.font-display-article {
  font-family: var(--font-display);
  font-style: normal;
  font-weight: 400;
}

.font-display-shell,
.font-display-section,
.font-display-numerals {
  font-family: var(--font-display);
  font-style: normal;
  font-weight: 600;
}

/*
 * The page masthead every route shares: an uppercase eyebrow, one DM Sans
 * display H1, a Geist lead and a muted meta line. Measured on the
 * reference: H1 87.36px at 1440 with 0.93 leading, eyebrow 13-14px tracked
 * +0.08em, lead 16/26 capped at 960px.
 */
.eyebrow {
  font-family: var(--font-sans);
  font-size: 13px;
  font-weight: 500;
  line-height: 1.2;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--muted);
}

.eyebrow a {
  color: inherit;
  text-decoration: underline;
  text-decoration-thickness: 1px;
  text-underline-offset: 3px;
  text-decoration-color: color-mix(in srgb, var(--muted) 60%, transparent);
}

.eyebrow a:hover {
  color: var(--ink);
}

/* A display numeral set as an eyebrow (the 404 status) keeps the eyebrow's
   size and tracking and takes the display face at its registered weight. */
.eyebrow.font-display-numerals {
  font-family: var(--font-display);
  font-weight: 600;
}

.display-h1 {
  font-family: var(--font-display);
  font-weight: 400;
  font-size: clamp(2.75rem, 0.6rem + 5.4vw, 5.46rem);
  line-height: 0.93;
  letter-spacing: -0.025em;
  color: var(--ink);
  overflow-wrap: break-word;
}

.page-lead {
  max-width: 960px;
  font-family: var(--font-sans);
  font-size: 16px;
  line-height: 1.62;
  color: var(--ink);
}

.meta-line {
  font-family: var(--font-sans);
  font-size: 15px;
  line-height: 1.5;
  color: var(--muted);
}

.meta-line a {
  color: var(--muted);
  text-decoration: underline;
  text-decoration-thickness: 1px;
  text-underline-offset: 3px;
}

.meta-line a:hover {
  color: var(--ink);
}

/*
 * Section labels outside the article (hub, home, index pages) wear the same
 * H2 as the article: DM Sans 600, 20px, uppercase, +0.055em.
 */
.section-h2 {
  font-family: var(--font-display);
  font-size: 20.32px;
  font-weight: 600;
  line-height: 1.3;
  letter-spacing: 0.055em;
  text-transform: uppercase;
  color: var(--ink);
}

/*
 * The sheet every non-article route sits on: the article's 960px column,
 * centred, with the same gutters, and the same masthead rhythm.
 */
.sheet {
  width: 100%;
  max-width: calc(960px + 2 * var(--article-gutter));
  margin-inline: auto;
  padding-inline: var(--article-gutter);
}

.sheet-masthead {
  padding-top: clamp(56px, 8vw, 128px);
}

.sheet-masthead .eyebrow {
  margin-bottom: 24px;
}

.sheet-masthead .page-lead {
  margin-top: 30px;
}

.sheet-masthead .meta-line {
  margin-top: 24px;
}

.sheet-section {
  margin-top: 76px;
}

.sheet-section > .section-h2 {
  margin-bottom: 18px;
}

/*
 * Home is the one index that has to show its whole contents in the first
 * screen: all seven domains above the fold at 1440x900 and the featured
 * scene starting within 1200px. Its masthead puts the search beside the
 * lead, and its sections close up to 48px, the same rules and type at a
 * front-page density.
 */
.sheet-masthead.home-masthead {
  padding-top: 32px;
}

.home-masthead .page-lead {
  margin-top: 20px;
}

.home-masthead .meta-line {
  margin-top: 12px;
}

@media (min-width: 1024px) {
  .home-masthead {
    display: grid;
    grid-template-columns: minmax(0, 1fr) 22rem;
    grid-template-rows: 1fr auto;
    column-gap: 48px;
  }

  .home-masthead > .home-lockup {
    grid-column: 1;
    grid-row: 1 / span 2;
  }

  /* The counts and the search share the right column; the search's bottom
     edge lines up with the lead's. */
  .home-masthead > .meta-line {
    grid-column: 2;
    grid-row: 1;
    align-self: end;
    margin: 0 0 12px;
  }

  .home-masthead > .home-masthead-search {
    grid-column: 2;
    grid-row: 2;
    align-self: end;
    margin-top: 0;
  }
}

.sheet-section.home-section {
  margin-top: 40px;
}

.home-section > .section-h2 {
  margin-bottom: 16px;
}

/*
 * The featured article and the featured scene: the article's title set in
 * the display face, then a dek written for home; the scene's caption takes
 * the dek's type above the explainer's stage, which runs the sheet's full
 * width.
 */
.home-feature-title {
  font-family: var(--font-display);
  font-size: clamp(1.5rem, 1.15rem + 1.1vw, 2rem);
  font-weight: 600;
  line-height: 1.15;
  letter-spacing: -0.01em;
  color: var(--ink);
  text-wrap: balance;
}

.home-feature-dek {
  max-width: 62ch;
  font-family: var(--font-sans);
  font-size: 18px;
  line-height: 1.55;
  color: var(--ink);
  text-wrap: pretty;
}

.home-feature-title + .home-feature-dek {
  margin-top: 10px;
}

.home-explainer > .home-feature-dek {
  margin-bottom: 14px;
}

.home-explainer-source {
  margin-top: 14px;
}

/* On a phone the explainer's stage is 4:5 while its poster is the 16:10
   desktop still, so home crops the poster to the stage, centred on the
   scene, and the robot fills it rather than sitting in a letterbox until
   the reader starts the 3D scene. */
@container (max-width: 560px) {
  .home-explainer .stage[data-mode='poster'] .poster {
    object-fit: cover;
  }
}

/* A plain text link in the house manner: ink, 1px underline. */
.ink-link {
  color: var(--ink);
  text-decoration: underline;
  text-decoration-thickness: 1px;
  text-decoration-color: color-mix(in srgb, var(--ink) 55%, transparent);
  text-underline-offset: 3px;
}

.ink-link:hover {
  text-decoration-color: var(--ink);
}

/* A quiet text link: muted until hovered, no underline at rest. */
.quiet-link {
  color: var(--muted);
  text-decoration: none;
}

.quiet-link:hover {
  color: var(--ink);
}

@layer base {
  html {
    scroll-padding-top: calc(var(--topbar-height) + 24px);
  }

  :root {
    color-scheme: light;
    --space-4: 4px;
    --space-8: 8px;
    --space-12: 12px;
    --space-16: 16px;
    --space-24: 24px;
    --space-32: 32px;
    --space-48: 48px;
    --space-64: 64px;
    --space-96: 96px;
    --space-128: 128px;
  }

  body {
    background: var(--paper);
    color: var(--ink);
    font-family: var(--font-sans);
    font-size: 16px;
    line-height: 1.5;
    -webkit-font-smoothing: antialiased;
    text-rendering: optimizeLegibility;
  }

  ::selection {
    background: var(--color-selection);
    color: var(--ink);
  }

  /* Focus is a 1px ink outline offset 2px, keyboard only. */
  :focus-visible {
    outline: 1px solid var(--color-focus);
    outline-offset: 2px;
    border-radius: 0;
  }

  :focus:not(:focus-visible) {
    outline: none;
  }

  /* Global reduced-motion guard. */
  @media (prefers-reduced-motion: reduce) {
