      animation-iteration-count: 1 !important;
      transition-duration: 0.01ms !important;
      scroll-behavior: auto !important;
    }
  }
}

/*
 * The Pantheon sheet is plain white paper: no grid, no grain pattern, no
 * halftone. The concrete and halftone materials are retired; paper is the one
 * material left, and the grid class survives as a name only.
 */
.engineering-grid,
.material-paper {
  background-color: var(--paper);
  background-image: none;
}

/*
 * The rule between an article's prose and its generated apparatus: one
 * hairline, like every other rule on the page.
 */
article > hr {
  border: 0;
  border-top: 1px solid var(--line);
  height: 0;
  background: none;
}

/*
 * A run of links set inline, like the article lists in the home contents.
 * The separating dot is generated content with empty alternative text, so
 * it is neither read aloud nor counted as a word of the page. Generated
 * content leaves no gap in the page text either, so each item after the
 * first opens with a real space; without it innerText, copying and reader
 * views join the last word of one title to the first word of the next. The
 * dot's end margin gives up about the width of that space, and a line can
