.skip-link {
  position: fixed;
  top: 0.75rem;
  left: 0.75rem;
  z-index: 100;
  transform: translateY(-300%);
  padding: 0.5rem 0.75rem;
  border: 1px solid var(--ink);
  background: var(--paper);
  color: var(--ink);
  font-family: var(--font-sans);
  font-size: 0.8125rem;
  text-decoration: none;
}

.skip-link:focus-visible {
  transform: none;
}

/*
 * The article sheet (Pantheon research page). One 960px reading column,
 * centred. From 1200px the sheet is a three-column grid: a sticky table of
 * contents in the left rail, the column, and the right margin the sidenotes
 * float into. Below 1200px it is one column; the contents become a
 * disclosure and the notes expand inline.
 */
:root {
  --prose-size: 16px;
  --prose-leading: 1.62;
  --prose-measure: 960px;
  --article-gutter: 24px;
  --article-col-gap: clamp(24px, 2.2vw, 36px);
  --rail-width: 172px;
  --note-width: 180px;
  --topbar-height: 76px;
}

@media (min-width: 640px) {
  :root {
    --article-gutter: 32px;
  }
}

[data-prose-column] {
  max-width: calc(var(--prose-measure) + 2 * var(--article-gutter));
  margin-inline: auto;
  padding-inline: var(--article-gutter);
  font-family: var(--font-sans);
  font-size: var(--prose-size);
}

@media (min-width: 1200px) {
  [data-prose-column] {
    max-width: none;
    display: grid;
    grid-template-columns:
      minmax(var(--rail-width), 1fr)
      minmax(0, var(--prose-measure))
      minmax(var(--note-width), 1fr);
    column-gap: var(--article-col-gap);
    padding-inline: clamp(24px, 3.3vw, 48px);
  }

  [data-prose-column] > * {
    grid-column: 2;
    min-width: 0;
  }

  [data-prose-column] > [data-article-rail] {
    grid-column: 1;
    grid-row: 2 / span 8;
  }
}

/* The masthead of an article: eyebrow, H1, lead and meta line. */
.article-masthead {
  padding-top: clamp(56px, 8vw, 128px);
}

.article-masthead .eyebrow {
  margin-bottom: 24px;
}

/*
 * The article title: the display H1, scaling from 40px on a phone to 87px
 * at 1440. Its phone floor sits 4px under the page H1's because a title
 * word has to fit one line of the 327px column: "Counterargument" sets
 * 345px wide at 44px and 318px at 40px, the lowest size VAL-B2-TYPE-007
 * allows. Hyphenation cannot carry that word: Chromium never auto-hyphenates
 * a capitalised English word, so `hyphens: auto` breaks only the lowercase
 * ones (the root element declares lang="en"), and a word wider than the
 * line would still break with no hyphen.
 */
.article-title {
  font-family: var(--font-display);
  font-weight: 400;
  font-size: clamp(2.5rem, 0.6rem + 5.4vw, 5.46rem);
  line-height: 0.93;
  letter-spacing: -0.025em;
  color: var(--ink);
  overflow-wrap: break-word;
  hyphens: auto;
}

.article-masthead .page-lead {
  margin-top: 30px;
}

.article-masthead .meta-line {
  margin-top: 24px;
}

/*
 * The left rail: the contents of the page, plain Geist, muted, the current
 * section in ink. Sticky under the top bar at 1200px and up; below that it
