 */
.article-toc {
  display: none;
}

.article-toc ol,
.article-contents ol {
  list-style: none;
  margin: 0;
  padding: 0;
}

.article-toc li + li {
  margin-top: 13px;
}

.article-toc a,
.article-contents a {
  display: block;
  color: var(--muted);
  font-family: var(--font-sans);
  font-size: 14.5px;
  line-height: 1.35;
  text-decoration: none;
  transition: color 160ms ease;
}

.article-toc a:hover,
.article-contents a:hover {
  color: var(--ink);
}

.article-toc a[aria-current],
.article-contents a[aria-current] {
  color: var(--ink);
  font-weight: 500;
}

.article-contents {
  margin-top: 48px;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}

.article-contents summary {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 0;
  cursor: pointer;
  list-style: none;
  color: var(--ink);
  font-family: var(--font-sans);
  font-size: 13px;
  font-weight: 500;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.article-contents summary::-webkit-details-marker {
  display: none;
}

.article-contents summary::after {
  content: '+' / '';
  font-family: var(--font-mono);
  font-size: 15px;
  font-weight: 400;
  letter-spacing: 0;
  color: var(--muted);
}

.article-contents[open] summary::after {
  content: '\2212' / '';
}

.article-contents ol {
  padding-bottom: 16px;
}

.article-contents li + li {
  margin-top: 10px;
}

@media (min-width: 1200px) {
  .article-toc {
    display: block;
    position: sticky;
    top: calc(var(--topbar-height) + 40px);
    align-self: start;
    max-height: calc(100dvh - var(--topbar-height) - 64px);
    overflow-y: auto;
    padding-top: 4px;
